import React,{useState} from 'react';
import {Modal} from '../../shared/preferences.tsx';
import {ResourceState} from '../../shared/ui.jsx';
import {useBoard} from './useBoard.js';
const short=(s,count=15)=>Array.from(s||'').length>count?Array.from(s).slice(0,count).join('')+'…':s;
const unique=values=>[...new Set(values)];
const marks={plant:'● 埋设',progress:'◆ 推进',recover:'✓ 回收',target:'◇ 计划回收'};
const kinds={linear:'顺叙',flashback:'倒叙',insert:'插叙',background:'背景'};
export function SvgAction({x,y,label,title,onClick,color='var(--cg-ink)',size=13}){return <g role="button" tabIndex={0} aria-label={title||label} onClick={onClick} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();onClick?.();}}} className="svg-action"><title>{title||label}</title><rect x={x-5} y={y-17} width={Math.max(28,Math.min(168,Array.from(label).length*size+10))} height="26" rx="5" fill="transparent"/><text x={x} y={y} fill={color} fontSize={size}>{label}</text></g>;}
export function ChronologyPanel({call,novelId,tick,busy,onChapter,onMemory,onEvent,onForeshadow,onPlanning,mode='narration',nodeId}){
 const resource=useBoard(call,novelId,tick);
 return <section className="connected-panel"><div className="row"><h2 className="grow">{mode==='story'?'故事发生图':'章节叙述图'}</h2><button disabled={busy} onClick={()=>onEvent(null,true)}>＋ 事件</button></div><ResourceState resource={resource}>{resource.value&&<ChronologyChart board={resource.value} {...{mode,nodeId,onChapter,onMemory,onEvent,onForeshadow,onPlanning}}/>}</ResourceState></section>;
}
export function ChronologyChart({board,mode='narration',nodeId,onChapter,onMemory,onEvent,onForeshadow,onPlanning}){
 const [start,setStart]=useState(0),[spacing,setSpacing]=useState(210),[selected,setSelected]=useState(null);
 const lookup=(collection,id)=>board[collection].find(v=>v.id===id),events=board.events.filter(e=>!e.deleted&&(!nodeId||e.memoryRefs.includes(nodeId))),count=mode==='story'?events.length:board.chapters.length,offset=Math.min(start,Math.max(0,Math.floor((count-1)/20)*20));
 const chapters=board.chapters.slice(offset,offset+20),shown=events.slice(offset,offset+20),height=mode==='story'?Math.max(260,90+Math.min(board.nodes.length,25)*48):100+chapters.length*112;
 const eventNames=ids=>ids.map(id=>lookup('events',id)).filter(Boolean),personNames=ids=>ids.map(id=>lookup('nodes',id)).filter(Boolean);
 return <><div className="chart-tools"><span>{mode==='story'?'横向是明确的事件顺序，纵向是参与资料；间隔不代表日期长度。':'纵向跟随正文目录；横向对齐事件、已确认出场和伏笔。'}</span>{mode==='story'&&<label>间距<input aria-label="故事图间距" type="range" min="160" max="300" value={spacing} onChange={e=>setSpacing(Number(e.target.value))}/></label>}<div><button disabled={!offset} onClick={()=>setStart(Math.max(0,offset-20))}>上一段</button><small>{count?`${offset+1}–${Math.min(offset+20,count)} / ${count}`:'尚无记录'}</small><button disabled={offset+20>=count} onClick={()=>setStart(offset+20)}>下一段</button></div></div><p className="muted chart-hint">拖动图表区域可横向查看，点击事件、人物或伏笔可编辑同一份记录。</p>
 {!count?<div className="chart-empty">{mode==='story'?'还没有故事事件。添加事件后，角色与世界会串成轨迹。':'还没有正文。创建章节后，这里会按目录展现故事推进。'}</div>:<div className="chronology-scroll" tabIndex={0} aria-label={mode==='story'?'故事时间线图表，横向滚动':'章节叙述时间线图表，横向滚动'}>{mode==='story'?<StoryPlot board={board} events={shown} spacing={spacing} {...{nodeId,onMemory,onEvent,onForeshadow}}/>:<svg width="820" height={height} viewBox={`0 0 820 ${height}`} role="group" aria-label="章节、事件、人物与伏笔联动图"><rect width="820" height={height} fill="var(--cg-paper)"/>{[['正文目录',18],['发生事件',210],['人物实际出场',425],['伏笔埋设／回收',635]].map(([label,x])=><text key={label} x={x} y="30" fill="var(--cg-muted)" fontSize="13">{label}</text>)}
 {chapters.length>1&&<path d={`M190 71V${71+(chapters.length-1)*112}`} stroke="var(--cg-line)" strokeWidth="2"/>}
 {board.foreshadows.map((f,i)=>{const plant=board.chapters.findIndex(c=>c.id===f.firstPlantChapterId),end=board.chapters.findIndex(c=>c.id===(f.firstRecoveryChapterId||f.targetChapterId));if(plant<0||end<0||Math.max(plant,end)<offset||Math.min(plant,end)>=offset+chapters.length)return null;const y=a=>Math.min(chapters.length-1,Math.max(0,a-offset))*112+75;return <path key={f.id} d={`M${622+i%4*3},${y(plant)} L${622+i%4*3},${y(end)}`} stroke={f.firstRecoveryChapterId?'#42a592':'#b882da'} strokeWidth="2" strokeDasharray={f.firstRecoveryChapterId?undefined:'5 5'} opacity=".65"><title>{f.title}：{f.firstRecoveryChapterId?'埋设至实际回收':'埋设至计划回收'}</title></path>;})}
 {chapters.map((ch,i)=>{const y=75+i*112,people=personNames(unique(ch.characters.map(p=>p.id)));return <g key={ch.id}><path d={`M10 ${y+77}H805`} stroke="var(--cg-line)"/><circle cx="190" cy={y-4} r="4" fill="var(--cg-accent)"/><SvgAction x={18} y={y} label={`${offset+i+1}. ${short(ch.title,11)}`} title={`打开章节 ${ch.title}`} onClick={()=>onChapter(ch.id)}/><text x="18" y={y+26} fill="var(--cg-muted)" fontSize="12">{ch.words.toLocaleString()} 字</text>{!ch.events.length&&<SvgAction x={210} y={y} label="＋ 本章事件" title={`为 ${ch.title} 添加事件`} onClick={()=>onEvent(null,{chapterId:ch.id,revision:ch.revision})} color="var(--cg-muted)"/>}{eventNames(ch.events).slice(0,2).map((e,j)=><SvgAction key={e.id} x={210} y={y+j*28} label={`● ${short(e.title,12)}`} title={`编辑事件 ${e.title}`} onClick={()=>onEvent(e.id)} color="var(--cg-accent)"/>)}{people.slice(0,2).map((p,j)=><SvgAction key={p.id} x={425} y={y+j*28} label={short(p.name,12)} title={`打开人物 ${p.name}`} onClick={()=>onMemory(p.id)} color="var(--card-character,#b882da)"/>)}{ch.foreshadows.slice(0,2).map((r,j)=>{const f=lookup('foreshadows',r.id);return <SvgAction key={`${r.id}:${r.kind}`} x={635} y={y+j*28} label={`${marks[r.kind]} ${short(f?.title,8)}`} title={`${marks[r.kind]}：${f?.title}`} onClick={()=>onForeshadow(r.id)} color={r.kind==='recover'?'#42a592':r.kind==='target'?'#c99740':'#b882da'}/>;})}<SvgAction x={210} y={y+59} label={`本章联动 · ${ch.planning.length} 条规划`} title={`查看 ${ch.title} 全部联动资料`} onClick={()=>setSelected(ch)} size={12} color="var(--cg-muted)"/></g>;})}</svg>}</div>}
 {selected&&<Modal title={`${selected.title} · 联动资料`} close={()=>setSelected(null)} className="chapter-materials-modal"><button onClick={()=>onChapter(selected.id)}>打开正文</button><h3>事件</h3>{eventNames(selected.events).map(e=><p key={e.id}><button onClick={()=>onEvent(e.id)}>{e.title}</button> · {e.storyTime||'时间未注明'} · {kinds[e.narrativeKind]}</p>)}<h3>已确认实际出场</h3>{personNames(unique(selected.characters.map(p=>p.id))).map(p=><button key={p.id} onClick={()=>onMemory(p.id)}>{p.name}</button>)}<h3>伏笔</h3>{selected.foreshadows.map((r,i)=><p key={i}><button onClick={()=>onForeshadow(r.id)}>{marks[r.kind]} · {lookup('foreshadows',r.id)?.title}</button></p>)}<h3>相关规划</h3>{selected.planning.map(id=><button key={id} onClick={()=>onPlanning(id)}>{lookup('planning',id)?.title}</button>)}</Modal>}
 </>;
}
function StoryPlot({board,events,spacing,nodeId,onMemory,onEvent,onForeshadow}){
 const people=board.nodes.filter(n=>(!nodeId||n.id===nodeId)&&events.some(e=>e.memoryRefs.includes(n.id))),shadows=board.foreshadows.filter(f=>(!nodeId||f.memoryRefs.includes(nodeId))&&events.some(e=>e.foreshadowRefs.includes(f.id))).map(f=>({...f,name:f.title,type:'foreshadow'}));
 const rows=[...people,...shadows].slice(0,25),width=Math.max(650,190+events.length*spacing),height=Math.max(260,100+rows.length*52),included=(e,n)=>n.type==='foreshadow'?e.foreshadowRefs.includes(n.id):e.memoryRefs.includes(n.id),color=n=>n.type==='character_card'?'var(--card-character,#b882da)':n.type==='foreshadow'?'#c99740':'var(--card-world,#42a592)';
 return <div className="story-plot" style={{width,height}}><div className="story-fixed-labels" style={{height}}><small>参与资料／伏笔</small>{rows.map((n,j)=><button key={`${n.type}:${n.id}`} style={{top:87+j*52,color:color(n)}} onClick={()=>n.type==='foreshadow'?onForeshadow(n.id):onMemory(n.id)} title={n.name}>{n.type==='character_card'?'角色':n.type==='foreshadow'?'伏笔':'世界'} · {short(n.name,9)}</button>)}</div><svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} role="group" aria-label="故事事件与角色世界伏笔轨迹图"><rect width={width} height={height} fill="var(--cg-paper)"/>{events.map((e,i)=>{const x=190+i*spacing;return <g key={e.id}><path d={`M${x} 70V${height-15}`} stroke="var(--cg-line)" strokeDasharray="4 4"/><text x={x-20} y="24" fill="var(--cg-muted)" fontSize="12">{short(e.storyTime||`排序 ${e.order}`,16)}</text><SvgAction x={x-20} y={49} label={short(e.title,14)} title={`编辑事件 ${e.title}`} onClick={()=>onEvent(e.id)} color="var(--cg-accent)"/></g>;})}{rows.map((n,j)=>{const y=105+j*52,points=events.flatMap((e,i)=>included(e,n)?[190+i*spacing]:[]);return <g key={`${n.type}:${n.id}`}><path d={`M175 ${y}H${width-15}`} stroke="var(--cg-line)"/>{points.length>1&&<path d={`M${points[0]} ${y}H${points.at(-1)}`} stroke={color(n)} strokeWidth="3" opacity=".6"/>}{events.map((e,i)=>included(e,n)&&<g key={e.id} role="button" tabIndex={0} aria-label={`${n.name} 关联 ${e.title}`} className="svg-action" onClick={()=>onEvent(e.id)} onKeyDown={key=>{if(key.key==='Enter')onEvent(e.id);}}><title>{n.name} · {e.title}（事件关联，不自动确认出场或回收）</title><circle cx={190+i*spacing} cy={y} r="8" fill={color(n)}/></g>)}</g>;})}{!rows.length&&<text x="180" y="130" fill="var(--cg-muted)">事件尚未关联资料，可点击事件添加。</text>}{rows.length===25&&<text x="180" y={height-7} fontSize="11" fill="var(--cg-muted)">当前显示前 25 条参与资料。</text>}</svg></div>;
}
